const DB_PATH = '/home/user/qwik-app/data/bookmarks.db';

// Ensure directory exists
mkdirSync(dirname(DB_PATH), { recursive: true });

let dbInstance: Database.Database | null = null;

export function getDb() {
  if (!dbInstance) {
    dbInstance = new Database(DB_PATH);
    dbInstance.pragma('foreign_keys = ON');

    // Create tables if they don't exist
    dbInstance.exec(`
      CREATE TABLE IF NOT EXISTS bookmarks (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        url TEXT NOT NULL,
        title TEXT NOT NULL
      );

      CREATE TABLE IF NOT EXISTS tags (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT UNIQUE NOT NULL
      );

      CREATE TABLE IF NOT EXISTS bookmark_tags (
        bookmark_id INTEGER NOT NULL,
        tag_id INTEGER NOT NULL,
        PRIMARY KEY (bookmark_id, tag_id),
        FOREIGN KEY (bookmark_id) REFERENCES bookmarks (id) ON DELETE CASCADE,
        FOREIGN KEY (tag_id) REFERENCES tags (id) ON DELETE CASCADE
      );
    `);
  }
  return dbInstance;
}

export interface Bookmark {
  id: number;
  url: string;
  title: string;
  tags: string[];
}

export function getBookmarks(filterTags?: string[]): Bookmark[] {
  const db = getDb();

  let matchingIds: number[] = [];

  if (filterTags && filterTags.length > 0) {
    // Deduplicate filter tags
    const uniqueFilterTags = Array.from(new Set(filterTags.map(t => t.trim()).filter(Boolean)));

    if (uniqueFilterTags.length === 0) {
      // If there were filter tags but they were empty strings, get all
      const rows = db.prepare('SELECT id FROM bookmarks').all() as { id: number }[];
      matchingIds = rows.map(r => r.id);
    } else {
      // Find bookmark IDs that have all the unique filter tags
      const placeholders = uniqueFilterTags.map(() => '?').join(',');
      const query = `
        SELECT b.id
        FROM bookmarks b
        JOIN bookmark_tags bt ON b.id = bt.bookmark_id
        JOIN tags t ON bt.tag_id = t.id
        WHERE t.name IN (${placeholders})
        GROUP BY b.id
        HAVING COUNT(DISTINCT t.name) = ?
      `;

      const rows = db.prepare(query).all(...uniqueFilterTags, uniqueFilterTags.length) as { id: number }[];
      matchingIds = rows.map(r => r.id);
    }

    if (matchingIds.length === 0) {
      return [];
    }
  } else {
    // No filter tags, get all bookmark IDs
    const rows = db.prepare('SELECT id FROM bookmarks').all() as { id: number }[];
    matchingIds = rows.map(r => r.id);

    if (matchingIds.length === 0) {
      return [];
    }
  }

  // Fetch details and all tags for matching bookmarks
  const placeholders = matchingIds.map(() => '?').join(',');
  const query = `
    SELECT b.id, b.url, b.title, t.name AS tag_name
    FROM bookmarks b
    LEFT JOIN bookmark_tags bt ON b.id = bt.bookmark_id
    LEFT JOIN tags t ON bt.tag_id = t.id
    WHERE b.id IN (${placeholders})
    ORDER BY b.id ASC, t.name ASC
  `;

  const rows = db.prepare(query).all(...matchingIds) as { id: number; url: string; title: string; tag_name: string | null }[];

  const bookmarksMap = new Map<number, Bookmark>();
  for (const row of rows) {
    if (!bookmarksMap.has(row.id)) {
      bookmarksMap.set(row.id, {
        id: row.id,
        url: row.url,
        title: row.title,
        tags: []
      });
    }
    if (row.tag_name !== null) {
      bookmarksMap.get(row.id)!.tags.push(row.tag_name);
    }
  }

  return Array.from(bookmarksMap.values());
}

export function createBookmark(url: string, title: string, tags: string[]): Bookmark {
  const db = getDb();

  // Collapse duplicate tag names, trim and filter empty ones
  const processedTags = Array.from(
    new Set(
      tags
        .map(t => t.trim())
        .filter(t => t.length > 0)
    )
  );

  const insertTransaction = db.transaction(() => {
    // 1. Insert bookmark
    const bookmarkStmt = db.prepare('INSERT INTO bookmarks (url, title) VALUES (?, ?)');
    const result = bookmarkStmt.run(url, title);
    const bookmarkId = result.lastInsertRowid as number;

    // 2. Insert tags (or ignore if already exists) and get their IDs
    const tagStmt = db.prepare('INSERT OR IGNORE INTO tags (name) VALUES (?)');
    const selectTagStmt = db.prepare('SELECT id FROM tags WHERE name = ?');
    const insertJoinStmt = db.prepare('INSERT INTO bookmark_tags (bookmark_id, tag_id) VALUES (?, ?)');

    for (const tagName of processedTags) {
      tagStmt.run(tagName);
      const tagRow = selectTagStmt.get(tagName) as { id: number };
      insertJoinStmt.run(bookmarkId, tagRow.id);
    }

    return {
      id: bookmarkId,
      url,
      title,
      tags: [...processedTags].sort()
    };
  });

  return insertTransaction();
}

// Helper to get all distinct tags (useful for rendering tags in UI)
export function getAllTags(): string[] {
  const db = getDb();
  const rows = db.prepare('SELECT name FROM tags ORDER BY name ASC').all() as { name: string }[];
  return rows.map(r => r.name);
}

import type { RequestHandler } from '@builder.io/qwik-city';
import { getBookmarks, createBookmark } from '../../../db';

export const onGet: RequestHandler = async ({ url, json }) => {
  const tags = url.searchParams.getAll('tag');
  const bookmarks = getBookmarks(tags);
  json(200, bookmarks);
};

export const onPost: RequestHandler = async ({ request, json }) => {
  let body: any;
  try {
    body = await request.json();
  } catch (e) {
    json(400, { error: 'Invalid JSON body' });
    return;
  }

  if (!body) {
    json(400, { error: 'Body is required' });
    return;
  }

  const { url, title, tags } = body;

  if (typeof url !== 'string' || url.trim() === '') {
    json(400, { error: 'url is required and cannot be empty' });
    return;
  }

  if (typeof title !== 'string' || title.trim() === '') {
    json(400, { error: 'title is required and cannot be empty' });
    return;
  }

  let tagsArray: string[] = [];
  if (tags !== undefined) {
    if (!Array.isArray(tags)) {
      json(400, { error: 'tags must be an array of strings' });
      return;
    }
    tagsArray = tags.map(t => String(t));
  }

  try {
    const bookmark = createBookmark(url, title, tagsArray);
    json(201, bookmark);
  } catch (e: any) {
    json(500, { error: e.message || 'Internal server error' });
  }
};

import { component$ } from '@builder.io/qwik';
import { routeLoader$, routeAction$, zod$, z, Form } from '@builder.io/qwik-city';
import { getBookmarks, createBookmark, getAllTags } from '../db';

export const useBookmarksLoader = routeLoader$(({ url }) => {
  const tags = url.searchParams.getAll('tag');
  const bookmarks = getBookmarks(tags);
  const allTags = getAllTags();
  return {
    bookmarks,
    allTags,
    selectedTags: tags
  };
});

export const useCreateBookmarkAction = routeAction$(
  (data) => {
    const { url, title, tags } = data;
    const tagsArray = tags
      ? tags.split(',').map(t => t.trim()).filter(Boolean)
      : [];
    return createBookmark(url, title, tagsArray);
  },
  zod$({
    url: z.string().min(1, 'URL is required'),
    title: z.string().min(1, 'Title is required'),
    tags: z.string().optional()
  })
);

export default component$(() => {
  const loader = useBookmarksLoader();
  const action = useCreateBookmarkAction();

  return (
    <div>
      <h1>Tag-Filtered Bookmark Manager</h1>

      <section>
        <h2>Create a Bookmark</h2>
        <Form action={action}>
          <label>
            Title
            <input type="text" name="title" required />
          </label>
          <label>
            URL
            <input type="text" name="url" required />
          </label>
          <label>
            Tags (comma-separated)
            <input type="text" name="tags" placeholder="e.g. js, web, frontend" />
          </label>
          <button type="submit">Add Bookmark</button>
          {action.value?.id && <p style={{ color: 'green' }}>Bookmark added successfully!</p>}
        </Form>
      </section>

      <section>
        <h2>Filter by Tags</h2>
        <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap', marginBottom: '1.5rem' }}>
          {loader.value.allTags.map((tag) => {
            const isSelected = loader.value.selectedTags.includes(tag);
            const params = new URLSearchParams();
            let newTags = [...loader.value.selectedTags];
            if (isSelected) {
              newTags = newTags.filter(t => t !== tag);
            } else {
              newTags.push(tag);
            }
            newTags.forEach(t => params.append('tag', t));
            const href = params.toString() ? `/?${params.toString()}` : '/';

            return (
              <a
                key={tag}
                href={href}
                class={`tag ${isSelected ? 'selected' : ''}`}
                style={{
                  textDecoration: 'none',
                  display: 'inline-block',
                }}
              >
                {tag} {isSelected ? '✓' : ''}
              </a>
            );
          })}
          {loader.value.selectedTags.length > 0 && (
            <a href="/" style={{ color: 'red', textDecoration: 'none', alignSelf: 'center' }}>
              Clear Filters
            </a>
          )}
        </div>
      </section>

      <section>
        <h2>Bookmarks</h2>
        {loader.value.bookmarks.length === 0 ? (
          <p>No bookmarks found.</p>
        ) : (
          <div class="bookmark-list">
            {loader.value.bookmarks.map((bookmark) => (
              <div key={bookmark.id} class="bookmark-item" data-testid="bookmark-item">
                <h3 data-testid="bookmark-title">{bookmark.title}</h3>
                <p>
                  <a href={bookmark.url} target="_blank" rel="noopener noreferrer" data-testid="bookmark-url">
                    {bookmark.url}
                  </a>
                </p>
                <div class="tags">
                  {bookmark.tags.map((tag) => (
                    <span key={tag} class="tag">
                      {tag}
                    </span>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}
      </section>
    </div>
  );
});

